use op15_adaptive_harness::{loop_runner::TaskLoop, verifier::StaticVerifier, Budget,BudgetUse,LlamaCppClient,Task,Decision,verifier::Verdict};
#[test] fn loop_promotes_only_after_claim_bound_external_verdict() { let task=Task{id:"t".into(),claim:"claim".into(),tool_available:true,confidence_milli:700}; let verifier=StaticVerifier(Verdict{passed:true,oracle:"test".into(),artifact:"artifact".into(),verified_claim:Some("claim".into()),summary:"test oracle".into()}); let client=LlamaCppClient::local("F:\\tiers\\Nanbeige4.2-3B-Q8_0.gguf"); let r=TaskLoop::run(&task,Budget{wall_ms:5000,tokens:50,ram_mb:100,tool_calls:2},BudgetUse{wall_ms:100,tokens:10,ram_mb:1,tool_calls:1},&client,&verifier,2); assert_eq!(r.decision,Decision::Answer); assert_eq!(r.trace.0.len(),1); }
#[test] fn unrelated_verdict_cannot_promote_an_answer() { let task=Task{id:"t".into(),claim:"claim".into(),tool_available:true,confidence_milli:700}; let verifier=StaticVerifier(Verdict{passed:true,oracle:"test".into(),artifact:"artifact".into(),verified_claim:Some("other claim".into()),summary:"unrelated".into()}); let client=LlamaCppClient::local("F:\\tiers\\Nanbeige4.2-3B-Q8_0.gguf"); let r=TaskLoop::run(&task,Budget{wall_ms:5000,tokens:50,ram_mb:100,tool_calls:2},BudgetUse{wall_ms:100,tokens:10,ram_mb:1,tool_calls:1},&client,&verifier,2); assert_ne!(r.decision,Decision::Answer); }

